CREATE FUNCTION public.finance_source_snapshot(p_entry uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('date',j.entry_date,'venue',j.venue,'lines',(SELECT jsonb_agg(jsonb_build_object('id',l.id,'account_id',l.account_id,'debit',l.debit,'credit',l.credit,'mapping_status',l.mapping_status) ORDER BY l.id) FROM public.journal_lines l WHERE l.entry_id=j.id)) FROM public.journal_entries j WHERE j.id=p_entry $$;
REVOKE ALL ON FUNCTION public.finance_source_snapshot(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.finance_source_date_correct(p_entry uuid,p_date date,p_reason text,p_expected jsonb,p_reverse_only boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j public.journal_entries%ROWTYPE; r uuid;n uuid;op uuid;sid uuid;d date; BEGIN
SELECT * INTO j FROM public.journal_entries WHERE id=p_entry;
IF NOT FOUND OR NOT public.user_has_tenant(auth.uid(),j.tenant_id) OR NOT(public.has_role(auth.uid(),'admin') OR public.is_tenant_admin(j.tenant_id,auth.uid())) OR (j.venue_id IS NOT NULL AND NOT public.user_has_venue(auth.uid(),j.venue_id)) THEN RAISE EXCEPTION 'Finance access required';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended('finance-period:'||j.tenant_id::text,0)); SELECT * INTO j FROM public.journal_entries WHERE id=p_entry FOR UPDATE;
IF j.status<>'posted' OR j.source_type NOT IN ('invoice','sales_summary','adjustment') OR nullif(btrim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Unsupported source correction'; END IF;
IF public.finance_source_snapshot(j.id) IS DISTINCT FROM p_expected OR EXISTS(SELECT 1 FROM public.finance_source_operations WHERE original_entry_id=j.id) THEN RAISE EXCEPTION 'Source posting changed or already corrected';END IF;
IF EXISTS(SELECT 1 FROM public.finance_book_corrections WHERE original_entry_id=j.id) THEN RAISE EXCEPTION 'Existing correction requires review';END IF;
IF (SELECT round(sum(debit-credit),2) FROM public.journal_lines WHERE entry_id=j.id) IS DISTINCT FROM 0::numeric OR EXISTS(SELECT 1 FROM public.journal_lines WHERE entry_id=j.id AND account_id IS NULL) THEN RAISE EXCEPTION 'Unbalanced source posting';END IF;
IF NOT p_reverse_only AND (p_date IS NULL OR p_date>(now() AT TIME ZONE 'Asia/Hong_Kong')::date) THEN RAISE EXCEPTION 'Valid nonfuture source date required';END IF;
IF j.source_type='invoice' AND NOT p_reverse_only AND NOT EXISTS(SELECT 1 FROM public.invoices i WHERE i.id::text=j.source_id AND i.tenant_id=j.tenant_id AND i.invoice_date=p_date AND i.venue IS NOT DISTINCT FROM j.venue AND round(i.total_amount,2)=(SELECT round(sum(credit),2) FROM public.journal_lines WHERE entry_id=j.id)) THEN RAISE EXCEPTION 'Invoice source date, venue or total does not agree';END IF;
d:=j.entry_date; IF EXISTS(SELECT 1 FROM public.finance_closed_periods WHERE tenant_id=j.tenant_id AND month_start=date_trunc('month',d)::date AND reopened_at IS NULL) THEN d:=(now() AT TIME ZONE 'Asia/Hong_Kong')::date;END IF;PERFORM public.finance_assert_open(j.tenant_id,d);IF NOT p_reverse_only THEN PERFORM public.finance_assert_open(j.tenant_id,p_date);END IF;
SELECT id INTO sid FROM public.finance_source_postings WHERE current_entry_id=j.id FOR UPDATE;
INSERT INTO public.journal_entries(tenant_id,entry_date,memo,source_type,source_id,venue,venue_id,status,created_by,manually_adjusted) VALUES(j.tenant_id,d,'Reversal · '||p_reason,'adjustment','source_reverse:'||j.id,j.venue,j.venue_id,'draft',auth.uid(),true) RETURNING id INTO r;
INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,venue,venue_id,legacy_venue_name,line_no,memo,category_l1,payment_method,source_amount,mapping_rule_type,mapping_match_key,mapping_status) SELECT tenant_id,r,account_id,credit,debit,venue,venue_id,legacy_venue_name,line_no,'Reversal: '||coalesce(memo,''),category_l1,payment_method,-source_amount,mapping_rule_type,mapping_match_key,'reversed' FROM public.journal_lines WHERE entry_id=j.id; UPDATE public.journal_entries SET status='posted',posted_at=now() WHERE id=r;
IF NOT p_reverse_only THEN INSERT INTO public.journal_entries(tenant_id,entry_date,memo,source_type,source_id,venue,venue_id,status,created_by,manually_adjusted) VALUES(j.tenant_id,p_date,'Books updated · '||j.memo,'adjustment','source_replace:'||j.id,j.venue,j.venue_id,'draft',auth.uid(),true) RETURNING id INTO n;
INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,venue,venue_id,legacy_venue_name,line_no,memo,category_l1,payment_method,source_amount,mapping_rule_type,mapping_match_key,mapping_status) SELECT tenant_id,n,account_id,debit,credit,venue,venue_id,legacy_venue_name,line_no,memo,category_l1,payment_method,source_amount,mapping_rule_type,mapping_match_key,mapping_status FROM public.journal_lines WHERE entry_id=j.id;UPDATE public.journal_entries SET status='posted',posted_at=now() WHERE id=n;END IF;
INSERT INTO public.finance_source_operations(tenant_id,source_posting_id,original_entry_id,reversal_entry_id,replacement_entry_id,actor_id,reason,before_snapshot,after_snapshot) VALUES(j.tenant_id,sid,j.id,r,n,auth.uid(),p_reason,p_expected,jsonb_build_object('date',p_date,'reverse_only',p_reverse_only)) RETURNING id INTO op;
IF sid IS NOT NULL THEN UPDATE public.finance_source_postings SET current_entry_id=coalesce(n,r),revision=revision+1,source_snapshot=jsonb_build_object('date',p_date,'original_date',j.entry_date,'reversal_date',d,'reverse_only',p_reverse_only) WHERE id=sid;END IF;
INSERT INTO public.finance_book_corrections(tenant_id,original_entry_id,kind,reversal_entry_id,replacement_entry_id,corrected_date,reason,actor_id) VALUES(j.tenant_id,j.id,CASE WHEN p_reverse_only THEN 'reverse' ELSE 'date' END,r,n,p_date,p_reason,auth.uid());
INSERT INTO public.audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(j.tenant_id,auth.uid(),'source_books_updated','journal_entries',j.id::text,jsonb_build_object('operation',op,'date_before',j.entry_date,'date_after',p_date,'reversal',r,'replacement',n,'reason',p_reason));RETURN op;END $$;
REVOKE ALL ON FUNCTION public.finance_source_date_correct(uuid,date,text,jsonb,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_source_date_correct(uuid,date,text,jsonb,boolean) TO authenticated;
CREATE FUNCTION public.finance_source_drift(p_tenant uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.user_has_tenant(auth.uid(),p_tenant) OR NOT(public.has_role(auth.uid(),'admin') OR public.is_tenant_admin(p_tenant,auth.uid())) THEN RAISE EXCEPTION 'Finance access required';END IF;RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('entry_id',j.id,'source_id',i.id,'source_type','invoice','book_date',j.entry_date,'source_date',i.invoice_date,'book_venue',j.venue,'source_venue',i.venue,'book_total',a.total,'source_total',i.total_amount,'number',i.invoice_number,'date_only',j.venue IS NOT DISTINCT FROM i.venue AND a.total=round(i.total_amount,2))), '[]'::jsonb) FROM public.invoices i JOIN public.finance_source_postings p ON p.source_record_id=i.id AND p.source_type='invoice' AND p.tenant_id=i.tenant_id JOIN public.journal_entries j ON j.id=p.current_entry_id CROSS JOIN LATERAL (SELECT round(sum(credit),2) AS total FROM public.journal_lines WHERE entry_id=j.id)a WHERE i.tenant_id=p_tenant AND j.status='posted' AND (j.venue_id IS NULL OR public.user_has_venue(auth.uid(),j.venue_id)) AND (j.entry_date IS DISTINCT FROM i.invoice_date OR j.venue IS DISTINCT FROM i.venue OR a.total IS DISTINCT FROM round(i.total_amount,2)));END $$;
REVOKE ALL ON FUNCTION public.finance_source_drift(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.finance_source_drift(uuid) TO authenticated;